(()=>{const K="mipasantia_maqueta_v1",get=()=>JSON.parse(localStorage.getItem(K)||"{}"),set=d=>localStorage.setItem(K,JSON.stringify(d)),safe=s=>String(s).replace(/"/g,"&quot;");const decorate=()=>{let h=document.querySelector(".hero-art");if(h)h.style.zIndex="0";let mark=document.querySelector(".brand-mark");if(mark&&!mark.querySelector("img"))mark.innerHTML='<img class="brand-logo" src="assets/img/logo-mipasantia.png" alt="">';let f=document.querySelector("#publish-form");if(f&&!f.querySelector(".photo-field")){let a=f.querySelector(".form-actions");a.insertAdjacentHTML("beforebegin",'<div class="photo-field"><label for="story-photo">▧ Agregar una foto al relato</label><input id="story-photo" type="file" accept="image/png,image/jpeg,image/webp"><p class="photo-help">JPG, PNG o WebP. Se guarda solo en este navegador; máximo 1 MB.</p><div class="photo-preview"><img alt="Vista previa de la fotografía elegida"><button type="button" data-photo-clear>Quitar foto</button></div></div>')}let d=get();document.querySelectorAll(".card").forEach(c=>{let b=c.querySelector('[data-action="detail"]');if(!b||c.querySelector(".post-photo"))return;let p=(d.posts||[]).find(x=>x.id===Number(b.dataset.id));if(p&&p.foto)c.insertAdjacentHTML("afterbegin",'<img class="post-photo" src="'+safe(p.foto)+'" alt="Fotografía compartida con el relato '+safe(p.titulo)+'">')});let id=(location.hash.match(/^#detalle-(.+)$/)||[])[1],detail=document.querySelector(".detail");if(id&&detail&&!detail.querySelector(".detail-photo")){let p=(d.posts||[]).find(x=>String(x.id)===id);if(p&&p.foto){let title=detail.querySelector("h1");title.insertAdjacentHTML("afterend",'<img class="detail-photo" src="'+safe(p.foto)+'" alt="Fotografía compartida con el relato '+safe(p.titulo)+'">')}}};document.addEventListener("change",e=>{if(e.target.id!=="story-photo")return;let f=e.target.files[0],form=e.target.closest("form"),preview=form.querySelector(".photo-preview");if(!f)return;if(f.size>1048576){e.target.value="";form.dataset.photo="";preview.classList.remove("show");alert("Elegí una imagen de hasta 1 MB para que pueda guardarse en la maqueta.");return}let r=new FileReader;r.onload=()=>{form.dataset.photo=r.result;preview.querySelector("img").src=r.result;preview.classList.add("show")};r.readAsDataURL(f)});document.addEventListener("click",e=>{let b=e.target.closest("[data-photo-clear]");if(!b)return;let f=b.closest("form");f.dataset.photo="";f.querySelector("#story-photo").value="";f.querySelector(".photo-preview").classList.remove("show")});document.addEventListener("submit",e=>{let f=e.target;if(f.id!=="publish-form")return;e.preventDefault();e.stopImmediatePropagation();let x=Object.fromEntries(new FormData(f)),d=get(),u=(d.users||[]).find(z=>z.id===d.current),message=f.querySelector("#publish-message");if(!u)return;if(x.content.trim().length<40){message.innerHTML='<p class="notice error">Contá un poco más: el texto debe tener al menos 40 caracteres.</p>';return}d.posts=d.posts||[];d.posts.unshift({id:Date.now(),titulo:x.title.trim(),empresa:x.business.trim(),categoria:x.category,autor:u.nombre,fecha:new Date(x.date+"T12:00").toLocaleDateString("es-AR",{day:"2-digit",month:"short",year:"numeric"}),contenido:x.content.trim(),foto:f.dataset.photo||null});set(d);message.innerHTML='<p class="notice ok">Tu experiencia y su foto se guardaron en esta maqueta.</p>';f.reset();f.dataset.photo="";let p=f.querySelector(".photo-preview");if(p)p.classList.remove("show")},true);new MutationObserver(decorate).observe(document.body,{childList:true,subtree:true});decorate()})();
